-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.wild_aura_roll(p_species text, p_aura double precision)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case when sd.monster then null
              when p_aura < 1 / aura_form_odds() then 'glow'
              when p_aura < 2 / aura_form_odds() then 'spirit' end
    from species_def sd where sd.id = p_species
$function$
